def check_graph(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check degrees
    for i in range(n):
        if not (3 <= len(adj[i]) <= 7):
            return False, f"Vertex {i} has degree {len(adj[i])}"

    # Check girth
    for i in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    if dist[u] + dist[v] + 1 < 7:
                        return False, f"Cycle of length {dist[u] + dist[v] + 1} found"
    return True, "OK"

